- Expression-based field computation and safe evaluation

## Code Example

```javascript
// Minimal interface and sample mappers
class FieldMapper {
  transform(input) { throw new Error('Not implemented'); }
}
class PassThrough extends FieldMapper { transform(i) { return i; } }
class RenameFields extends FieldMapper { constructor(cfg){ super(); this.map = cfg; } transform(i){ const out={}; for(const k in i){ out[this.map[k]||k]=i[k]; } return out; } }
class ComputedFields extends FieldMapper { constructor(expr){ super(); this.expr=expr; } transform(i){ // naive eval
  const out={...i}; out.total = i.price * i.qty; return out; } }
class FlattenNested extends FieldMapper { constructor(cfg){ super(); this.path=cfg.path; } transform(i){ const v = i[this.path] || {}; return { ...i, ...v }; } }
